UInt8 nvfs_rd_nvram (UInt16 addr)
{
  UInt8 data ;

  nvfs_range_check (addr) ;

  if (!nvram_rd (addr , & data , 1))
    {
      nvfs_throw (NVFS_ERROR) ;
    }

  return data ;
}

